    {
      "criterion": "The cleanup line is positioned after the setInterval(...) call and inside the if (runStatusFilename) block.",
      "met": true
    },
    {
      "criterion": "When renderOrchestrator() is re-invoked, the _orchLogPreviewCleanups drain loop clears the interval (verifiable by code inspection or unit test).",
      "met": true
    },
    {
      "criterion": "No behavioural regression — the orchestrator view loads, polls status, and clears correctly.",
      "met": true
    }
